INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES
('14b45e2f-ef0e-5168-bc8b-cb0948556412', 'fa970257-ae84-5717-a392-4730c1f5b4f6', 'tr', $h$Mekanik Sıvı Transfer Pompası – 4011$h$, $h$mekanik-sivi-transfer-pompasi-4011$h$, NULL, $h$<div> <div><p><strong>Neden 4011 Mekanik Sıvı Transfer Pompası ?</strong></p><p>Elektrik veya farklı bir güç gerektirmeyen kollu sıvı transfer pompasını; solvent, yağ, mazot ve yanıcı olmayan sıvılar gibi birçok sıvının transferinde kullanırsınız. Diğer pompalara göre yüksek verim sunar ve onu ağır hizmet gerektiren uygulamalarda tercih edersiniz. Kolay kullanımı, uzun ömürlü yapısı, taşınabilirliği ve düşük işletme maliyeti sayesinde bu pompayı sıkça kullanırsınız.</p></div> </div>$h$, NULL, $h$Mekanik Sıvı Transfer Pompası – 4011 | HD Marine$h$, $h$Neden 4011 Mekanik Sıvı Transfer Pompası ? Elektrik veya farklı bir güç gerektirmeyen kollu sıvı transfer pompasını; solvent, yağ, mazot ve yanıcı olmayan…$h$, 'reviewed'),
('b2a1744e-826c-533b-8096-0e04150fbee9', '60839115-86b7-52b1-9d25-09d0c3637930', 'tr', $h$Mekanik Sıvı Transfer Pompası – 44100$h$, $h$mekanik-sivi-transfer-pompasi-44100$h$, NULL, $h$<div> <div><p><strong>Neden 44100 Mekanik Sıvı Transfer Pompası ?</strong></p><p>Bu basmalı sıvı transfer pompası, elektrik veya başka bir güç gerektirmez. Solvent, yağ, mazot ve yanıcı olmayan diğer sıvıları aktarır. Varile monte etmek için 2 inç bağlantısı bulunur. Kolay kullanımı, uzun ömrü, taşınabilirliği ve düşük işletme maliyeti sayesinde onu tercih edersiniz.</p></div> </div>$h$, NULL, $h$Mekanik Sıvı Transfer Pompası – 44100 | HD Marine$h$, $h$Neden 44100 Mekanik Sıvı Transfer Pompası ? Bu basmalı sıvı transfer pompası, elektrik veya başka bir güç gerektirmez. Solvent, yağ, mazot ve yanıcı…$h$, 'reviewed'),
('59147daa-f652-539f-a260-51dd035e005b', 'b31261cc-88ac-53b4-b6b2-f0270991f6d4', 'tr', $h$Gövdeden İtmeli Yağ Pompası – İYP$h$, $h$govdeden-itmeli-yag-pompasi-iyp$h$, NULL, $h$<div> <div><p><strong>Neden İYP Gövdeden İtmeli Yağ Pompası ?</strong></p><p>Kompakt yapısı sayesinde hızlı yağlama için idealdir. Metal gövdesi sayesinde darbelere karşı dayanıklıdır.</p></div> </div>$h$, NULL, $h$Gövdeden İtmeli Yağ Pompası – İYP | HD Marine$h$, $h$Neden İYP Gövdeden İtmeli Yağ Pompası ? Kompakt yapısı sayesinde hızlı yağlama için idealdir. Metal gövdesi sayesinde darbelere karşı dayanıklıdır.$h$, 'reviewed'),
